CREATE TRIGGER push_tenant BEFORE INSERT ON push_subscriptions WHEN NOT EXISTS(SELECT 1 FROM memberships WHERE id=NEW.membership_id AND company_id=NEW.company_id) BEGIN SELECT RAISE(ABORT,'push_identity_conflict'); END;
CREATE TRIGGER push_identity BEFORE INSERT ON push_subscriptions WHEN EXISTS(SELECT 1 FROM push_subscriptions p JOIN memberships old ON old.id=p.membership_id AND old.company_id=p.company_id JOIN memberships current ON current.id=NEW.membership_id AND current.company_id=NEW.company_id WHERE p.endpoint=NEW.endpoint AND old.user_id<>current.user_id) BEGIN SELECT RAISE(ABORT,'push_identity_conflict'); END;
